import numpy as np
one=np.ones_like(P)
E=np.exp(-0.5*P)
names=[];cols=[]
for k in range(3):
    for j in range(3):
        names.append(f"P^{k}t^{j}");cols.append(P**k*t**j)
for k in range(3):
    for j in range(3):
        names.append(f"E*P^{k}t^{j}");cols.append(E*P**k*t**j)
X=np.column_stack(cols)
c,*_=np.linalg.lstsq(X,dP_dt,rcond=None)
r=dP_dt-X@c
print("NMSE",np.mean(r**2)/np.var(dP_dt))
for n,v in zip(names,c): print(n, repr(float(v)))
